namespace WorkspaceAPIs.Entities;

/// <summary>
/// Represents a push notification generated by the system or manually created for announcements.
/// </summary>
[Table("Notifications")]
public class Notification : BaseEntity, IMustHaveTenant
{
    /// <summary>
    /// Gets or sets the unique identifier of the tenant for multi-tenancy architecture.
    /// </summary>
    public Guid TenantId { get; set; }

    /// <summary>
    /// Gets or sets the reference ID of the record associated with the notification.
    /// </summary>
    public Guid? RefId { get; set; }

    /// <summary>
    /// Gets or sets the message of the notification.
    /// </summary>
    [MaxLength(500)]
    public required string Message { get; set; }

    /// <summary>
    /// Gets or sets the type/category of the notification.
    /// </summary>
    [MaxLength(30)]
    public NotificationTypesEnum Type { get; set; }

    /// <summary>
    /// Gets or sets the action URL associated with the notification.
    /// </summary>
    [MaxLength(1000)]
    public string? ActionUrl { get; set; }

    /// <summary>
    /// Gets or sets a value indicating whether the notification was created manually by an admin or by the app.
    /// </summary>
    public bool IsSystemGenerated { get; set; } = true;

    /// <summary>
    /// Gets or sets the list of NotificationUsers associated with the notification.
    /// </summary>
    public virtual ICollection<NotificationUser>? NotificationUsers { get; set; }
}